import 'dart:convert';
import 'dart:math' as math;
import 'dart:typed_data';
import 'package:flutter/material.dart';

/// True vector contours traced from the user's bus drawing.
/// Stored as 91 even-odd paths, about 4.4 KB binary, with no image dependency.
class BusMuralPainter extends CustomPainter {
  const BusMuralPainter();

  static final Path bus = _decode();

  static Path _decode() {
    final bytes = base64Decode(_vectorData);
    final data = ByteData.sublistView(bytes);
    final path = Path()..fillType = PathFillType.evenOdd;
    var started = false;
    for (var i = 0; i + 3 < bytes.length; i += 4) {
      final x = data.getUint16(i, Endian.little);
      final y = data.getUint16(i + 2, Endian.little);
      if (x == 65535) {
        if (started) path.close();
        started = false;
      } else if (!started) {
        path.moveTo(x.toDouble(), y.toDouble());
        started = true;
      } else {
        path.lineTo(x.toDouble(), y.toDouble());
      }
    }
    if (started) path.close();
    return path;
  }

  @override
  void paint(Canvas canvas, Size size) {
    if (size.isEmpty) return;
    final scale = math.min(size.width / 1179.0, size.height / 505.0);
    canvas.save();
    canvas.translate(
      (size.width - 1179 * scale) * .5,
      (size.height - 505 * scale) * .5,
    );
    canvas.scale(scale);
    canvas.drawPath(bus, Paint()..color = const Color(0xff111112));

    // A few original spray-paint drips and overspray flecks.
    final paint = Paint()
      ..color = const Color(0xff151516).withValues(alpha: .83)
      ..strokeWidth = 2.7
      ..strokeCap = StrokeCap.round;
    for (final drop in <List<double>>[
      [126, 415, 446], [342, 460, 480], [826, 430, 454],
      [1080, 395, 418],
    ]) {
      canvas.drawLine(Offset(drop[0], drop[1]),
          Offset(drop[0], drop[2]), paint);
      canvas.drawCircle(Offset(drop[0], drop[2]), 1.3, paint);
    }
    final r = math.Random(8724);
    final mist = Paint()..color = const Color(0x21171819);
    for (var i = 0; i < 145; i++) {
      final x = 10 + r.nextDouble() * 1160;
      final y = 20 + r.nextDouble() * 470;
      canvas.drawCircle(Offset(x, y), .3 + r.nextDouble() * 1.25, mist);
    }
    canvas.restore();
  }

  @override
  bool shouldRepaint(covariant BusMuralPainter oldDelegate) => false;
}

const _vectorData =
    ''
    ''
    ''
    ''
    ''
    ''
    ''
    ''
    ''
    ''
    ''
    '';
